+// Edge worker example - runs on CDN with no database access
+//
+// The edge worker:
+// 1. Validates session tokens using cryptographic signatures (no DB)
+// 2. Maintains a local cache of revoked sessions
+// 3. Periodically syncs revocations from the main service via HTTP
+
+import { validateSessionTokenEdgeWorker, updateRevokedSessions } from "./session-store.ts";
+
+// Edge worker initialization: sync revocations from main service
+export const initializeEdgeWorker = async (mainServiceUrl: string) => {
+  // Poll revocations every 30 seconds to maintain < 60 second SLA
+  setInterval(async () => {
+    try {
+      const response = await fetch(`${mainServiceUrl}/api/revoked-sessions`);
+      const { sessionIds } = await response.json();
+      updateRevokedSessions(sessionIds);
+    } catch (err) {
+      console.error("Failed to sync revocations:", err);
+    }
+  }, 30_000);
+};
+
+// Edge worker API: validate a session token
+export const validateRequest = (sessionToken: string) => {
+  const session = validateSessionTokenEdgeWorker(sessionToken);
+  if (!session) {
+    return { valid: false, error: "Invalid or revoked session" };
+  }
+  return { valid: true, userId: session.userId };
+};
+
+// Example request handler
+export const handleReadRequest = (req: Request) => {
+  const authHeader = req.headers.get("authorization");
+  const token = authHeader?.replace("Bearer ", "");
+
+  if (!token) {
+    return new Response("Unauthorized", { status: 401 });
+  }
+
+  const validation = validateRequest(token);
+  if (!validation.valid) {
+    return new Response(validation.error, { status: 401 });
+  }
+
+  // Request is authenticated; serve the cached read data
+  return new Response("Data served from CDN edge", { status: 200 });
+};
