+// Main service API endpoints for session management
+// These enable the edge worker to operate independently
+
+import { issueSessionToken, revokeSession, syncRevokedSessionsFromDB, loadSession } from "./session-store.ts";
+
+// POST /api/sessions/:id/token
+// Issue a signed session token for the edge worker to validate
+export const issueToken = async (sessionId: string) => {
+  const session = await loadSession(sessionId);
+  if (!session) {
+    throw new Error("Session not found");
+  }
+  return {
+    token: issueSessionToken(sessionId, session.userId),
+    userId: session.userId,
+  };
+};
+
+// POST /api/sessions/:id/revoke
+// Revoke a session (immediate effect on main service)
+export const revokeSessionEndpoint = async (sessionId: string) => {
+  await revokeSession(sessionId);
+  // Sync to make sure revocation list is current
+  await syncRevokedSessionsFromDB();
+};
+
+// GET /api/revoked-sessions
+// Edge worker polls this to sync its local revocation cache
+// Returns session IDs revoked in the last 90 seconds
+export const getRevokedSessions = async () => {
+  await syncRevokedSessionsFromDB();
+  // In production, you'd fetch from DB or cache instead
+  // This is a simplified example
+  return {
+    sessionIds: [] as string[],
+    timestamp: Date.now(),
+  };
+};
