+// Test: Session token signing and verification
+import { signSessionToken, verifySessionToken } from "./session-crypto.ts";
+
+const testSignAndVerify = () => {
+  const token = signSessionToken("session-123", "user-456");
+  console.log("✓ Token created:", token.substring(0, 30) + "...");
+
+  const payload = verifySessionToken(token);
+  console.assert(payload !== null, "Payload should not be null");
+  console.assert(payload?.id === "session-123", "Session ID should match");
+  console.assert(payload?.userId === "user-456", "User ID should match");
+  console.log("✓ Token verified successfully");
+};
+
+const testTamperedToken = () => {
+  const token = signSessionToken("session-123", "user-456");
+  const parts = token.split(".");
+  const tamperedToken = parts[0] + ".invalidsignature";
+
+  const payload = verifySessionToken(tamperedToken);
+  console.assert(payload === null, "Tampered token should fail verification");
+  console.log("✓ Tampered token rejected");
+};
+
+const testInvalidFormat = () => {
+  const payload = verifySessionToken("invalid");
+  console.assert(payload === null, "Invalid format should return null");
+  console.log("✓ Invalid format rejected");
+};
+
+// Run tests
+testSignAndVerify();
+testTamperedToken();
+testInvalidFormat();
+console.log("\n✓ All tests passed!");
