+import crypto from "crypto";
+
+const SECRET_KEY = process.env.SESSION_SECRET_KEY || "dev-secret-key";
+
+interface TokenPayload {
+  id: string;
+  userId: string;
+  issuedAt: number;
+}
+
+export const signSessionToken = (
+  sessionId: string,
+  userId: string
+): string => {
+  const payload: TokenPayload = {
+    id: sessionId,
+    userId,
+    issuedAt: Date.now(),
+  };
+
+  const payloadJson = JSON.stringify(payload);
+  const payloadB64 = Buffer.from(payloadJson).toString("base64");
+  const signature = crypto
+    .createHmac("sha256", SECRET_KEY)
+    .update(payloadB64)
+    .digest("base64");
+
+  return `${payloadB64}.${signature}`;
+};
+
+export const verifySessionToken = (token: string): TokenPayload | null => {
+  const parts = token.split(".");
+  if (parts.length !== 2) return null;
+
+  const [payloadB64, signature] = parts;
+
+  const expectedSignature = crypto
+    .createHmac("sha256", SECRET_KEY)
+    .update(payloadB64)
+    .digest("base64");
+
+  if (signature !== expectedSignature) return null;
+
+  try {
+    const payloadJson = Buffer.from(payloadB64, "base64").toString("utf-8");
+    return JSON.parse(payloadJson);
+  } catch {
+    return null;
+  }
+};
