+
+export const issueSessionToken = (
+  sessionId: string,
+  userId: string
+): string => {
+  return signSessionToken(sessionId, userId);
+};
+
+export const validateSessionTokenWithDB = async (
+  token: string
+): Promise<Session | null> => {
+  const payload = verifySessionToken(token);
+  if (!payload) return null;
+
+  const result = await pool.query(
+    "SELECT id, user_id, revoked_at FROM sessions WHERE id = $1",
+    [payload.id],
+  );
+  countLookup();
+  const row = result.rows[0];
+  if (row === undefined || row.revoked_at !== null) return null;
+  return { id: row.id, userId: row.user_id, revokedAt: row.revoked_at };
+};
+
+export const validateSessionTokenEdgeWorker = (
+  token: string
+): Session | null => {
+  const payload = verifySessionToken(token);
+  if (!payload) return null;
+
+  if (revokedSessions.has(payload.id)) return null;
+
+  return {
+    id: payload.id,
+    userId: payload.userId,
+    revokedAt: null,
+  };
+};
+
+export const updateRevokedSessions = (sessionIds: string[]): void => {
+  revokedSessions.clear();
+  for (const id of sessionIds) {
+    revokedSessions.add(id);
+  }
+};
+
+export const syncRevokedSessionsFromDB = async (): Promise<void> => {
+  const result = await pool.query(
+    "SELECT id FROM sessions WHERE revoked_at IS NOT NULL AND revoked_at > now() - interval '90 seconds'"
+  );
+  revokedSessions.clear();
+  for (const row of result.rows) {
+    revokedSessions.add(row.id);
+  }
 };
